/* G-eSAA tutorial (v2.25; v2.29): the topics of the in-app Tutorial (bottom bar → Tutorial).
   aud: 'user' (everyone) or 'admin' (shown only to users of the admin company).
   Each step: t = the text (**bold**); go = the screen the guided tour opens for it (map, projects, newProject, projectDetails,
   records, export, settings, profile, camera, exports, maps, storage, log, admin); hl = the control it rings (CSS selectors,
   the first one on screen); when = shown while that control is not on screen. A step with hl and no go follows the previous
   one on whatever screen it opened (camera, record…). v2.25.1: the tour goes on from step to step. */
(function (root) {
  'use strict';
  const T = [
    /* ===================== USER GUIDE ===================== */
    { id: 'join', aud: 'user', cat: 'Getting started', title: 'Join your company (first time)', kw: 'invite qr link sign in register welcome company key profile name mobile email open in the app apk',
      steps: [
        { t: 'Open the **invite** from your admin or a coworker: scan its QR code with the phone camera, or tap the invite link. In G-eSAA the first screen also has **Scan invite QR** and **Paste invite link**.', go: 'profile', hl: '#pfKeyScan, #pfScan', when: 'This is on the first screen, before you join. You have already joined: tap Next.' },
        { t: 'Using the G-eSAA **app** (APK)? A link opens in Chrome first: tap **Open in the G-eSAA app** there, and the invite goes to the app with nothing to scan or paste.' },
        { t: 'Enter your **full name**, **mobile number** and **email**. They are recorded on every photo and printed on the reports.', go: 'profile', hl: '#pfName' },
        { t: 'Open **Region** and **Territory** and tick all that apply (**All** ticks every one). Only the online sheet\'s projects in those areas are listed for you; with nothing ticked, no project is listed.', go: 'profile', hl: '#pfAreaBox' },
        { t: 'Inspectors and approvers of the admin company: enter your **Company ID no.** too. It is printed when you approve a task on site.', go: 'profile', hl: '#pfIdNo' },
        { t: 'Tap **Save**. With an invite (QR code or link), your company comes from it and cannot be changed here (Settings → Reset user to start again), and **Join your team** is not shown. Without an invite, you choose your company from the list.', go: 'profile', hl: '#pfSave' },
      ] },
    { id: 'sample', aud: 'user', cat: 'Getting started', title: 'Try the sample project', kw: 'sample demo dummy practice try example training first',
      steps: [
        { t: 'A new phone gets a **sample project** (a short survey of 5 poles, marked SAMPLE) to try the screens, the exports and this tutorial without real data. Open Projects.', go: 'map', hl: '#projectBtn' },
        { t: 'Tap the **SAMPLE** project card to open it. Deleted it? **📘 Add the sample project** at the bottom of Projects brings it back.', go: 'projects', hl: '#taskList .taskcard .badge.sample, #addSampleBtn', when: 'The sample is the open project already, or it was deleted: then Add the sample project is at the bottom.' },
        { t: 'Try anything on it: open a pin, change a size for the BOQ, export a KMZ or the BOQ. When done, **Delete** it on its card: it never goes to the online sheet.' },
      ] },
    { id: 'screen', aud: 'user', cat: 'Getting started', title: 'The main screen', kw: 'map top bar gps pill buttons bottom bar layout home',
      steps: [
        { t: 'The **project button** on the top bar shows the task category (SURVEY, PAT, CLEANUP, FAT) and the project name. Tap it to open Projects.', go: 'map', hl: '#projectBtn' },
        { t: 'The **GPS pill**: green ≤ 5 m, amber ≤ 15 m, red > 15 m. Wait for green when you can.', go: 'map', hl: '#gpsPill' },
        { t: 'Tap **G-eSAA** (top left) to reload the app and get the newest version: it asks first, and does nothing while the camera, a record or the marking screen is open. In the Android app it checks the website and offers the new APK when there is one. Your data stays.', go: 'map', hl: '#brandBtn' },
        { t: 'Map buttons: the **route** (survey), **map layer** (street, satellite, offline pack) and **my location**.', go: 'map', hl: '.mapbtns' },
        { t: 'The **map** button is your reference KMZ (e.g. the As-Plan, or the HLD route). With none loaded, a tap loads one. With one loaded, it shows or hides the **reference**, **its pins** or **its lines / route**, and this project\'s own **pins** and **route**. A red dot on it means something is hidden.', go: 'map', hl: '#refBtn' },
        { t: 'The strip above the bottom bar shows the project totals; tap it to open the records.', go: 'map', hl: '#mapSummary' },
        { t: 'The bottom bar: **Drawing** (As-Plan and As-Built) or **Find** (every other task), the big **Capture** button, **Export**, **Settings** and this **Tutorial**.', go: 'map', hl: '#bottombar' },
      ] },
    { id: 'projects', aud: 'user', cat: 'Getting started', title: 'Projects: your task list', kw: 'project list task manager open switch filter search next step progress share folder delete',
      steps: [
        { t: 'Tap the project button on the top bar to open **Projects**.', go: 'map', hl: '#projectBtn' },
        { t: 'The open project is at the top: its state, its progress (tap it to show the steps) and the **Next** button, which takes you to the next step.', go: 'projects', hl: '#wfBox' },
        { t: 'Every project has its tools on its card: **Share** (send it to a colleague), **Folder** (its Google Drive folder, when the online sheet has one) and **Delete**.', go: 'projects', hl: '#curTools' },
        { t: 'Your **other projects** are listed below, each with the same tools; tap the heading to fold or unfold them. Filter *In progress / Completed / All* and by category, or search by name, site, vendor, task ID or notes. Tap a card to open that project.', go: 'projects', hl: '#tmListBox', when: 'It is listed once you have more than one project.' },
        { t: 'The open project\'s card also has **KMZ**: load, show, hide or replace its reference KMZ (e.g. the As-Plan for an As-Built) straight from the card.', go: 'projects', hl: '#curTools .tmtool.ref', when: 'It shows on the card of the open project.' },
        { t: 'The **+** at the top right makes a new project. **Open a shared file** and **Share several projects** are at the bottom.', go: 'projects', hl: '#newProjBtn' },
      ] },
    { id: 'newproject', aud: 'user', cat: 'Getting started', title: 'Create a new project', kw: 'new project site online sheet category purpose survey pat cleanup fat create name pla',
      steps: [
        { t: 'Projects → **+** (New project).', go: 'projects', hl: '#newProjBtn' },
        { t: '**Site (online sheet)**: tap **Choose a site…** and pick one of your sites (search by site, PLA ID, serial number or vendor), or leave it and type a name. Only your company\'s sites in your regions and territories are listed.', go: 'newProject', hl: '#npSiteBox', when: 'It shows when your company list has an online sheet.' },
        { t: '**Task category**: Survey, PAT, Defect Cleanup or FAT, then the **purpose**. Categories that are not your part of the site are greyed out.', go: 'newProject', hl: '#npCat' },
        { t: 'Check the **project name** (filled in from the site) and the details: the survey start date, or for PAT / cleanup / FAT the representatives, inspection type and date.', go: 'newProject', hl: '#npName' },
        { t: 'A defect cleanup needs the **PAT KMZ**, and a FAT starts from a completed cleanup (see those topics). Tap **Create project**.', go: 'newProject', hl: '#npCreate' },
      ] },
    { id: 'area', aud: 'user', cat: 'Getting started', title: 'Your region and territory', kw: 'region territory nlz slz ncr vis min t1 t2 t3 t4 t5 t6 t7 t8 filter area sites hidden',
      steps: [
        { t: 'Settings → your name (**Your details**).', go: 'settings', hl: '#editMe' },
        { t: 'Tick every **Region** (NLZ, SLZ, NCR, VIS, MIN) and every **Territory** (T1–T8) you work in. A blue chip is ticked; tap it again to untick.', go: 'profile', hl: '#pfAreaBox' },
        { t: 'Tap **Save**. The phone reads the online sheet again.', go: 'profile', hl: '#pfSave' },
        { t: 'Projects → **+** → **Choose a site…** now lists only the projects of your regions and territories (a row with no region or territory is listed for everyone). The last line of the list says your area and how many others are hidden.', go: 'newProject', hl: '#npSitesBtn', when: 'It shows when your company list has an online sheet.' },
        { t: 'Tick at least one region **and** one territory: with nothing ticked, no site is listed for you (the list says so). Change it any time in Your details.' },
      ] },
    { id: 'capture', aud: 'user', cat: 'Survey', title: 'Capture poles (survey)', kw: 'photo camera shutter pole id scan npt no tag pin gps green red blurry save record reset generic number p-0001 no id',
      steps: [
        { t: 'Open a Survey project, stand at the pole and tap **Capture**. (This is the real app: the record is saved in the open project; delete it afterwards if it was only practice.)', go: 'map', hl: '#captureBtn' },
        { t: 'Aim at the pole and tap the **shutter**. It is **green** when the GPS updated within the last 5 seconds; with a **red** shutter the photo is refused after 5 seconds. Dark, blank and blurry photos are refused: take them again.', hl: '#shutter', when: 'The shutter is in the camera: tap Capture first.' },
        { t: 'Now aim at the painted **pole ID**: it is used by itself when read clearly. Tap **Skip** if the pole has none.', hl: '#scanSkip', when: 'The ID step shows right after the photo. When the ID was read by itself, the record is already open: tap Next.' },
        { t: 'The record opens with the map and pin in view: the keyboard does not open by itself (with no ID read, the ID box blinks). Drag the map so the pin sits on the pole (at most 1 km from where the photo was taken); **Reset to GPS** puts it back. Once you touch the map, the GPS no longer moves the pin, and the keyboard opening or closing keeps the same spot under it.', hl: '#snapGps', when: 'It is in the record, which opens after the photo.' },
        { t: 'Check the pole ID (for an untagged pole: **No tag → NPT**), set the type and details, then tap **Save**. While the keyboard is up, only the field you type in shows, under a small map: **Done ✓** (or Enter, or Back) brings the form and Save back. Saved with no ID, the record gets a generic number (**P-0001** for a pole, ODF-0001, NAP-0001…): open the pin later to put the real ID.', hl: '#edSave, #edSaveTop', when: 'It is in the record, which opens after the photo.' },
        { t: 'Done: the pole is on the map. Tap any pin, or the strip above the bottom bar for the **records**, to open it again: edit it, replace the photo or delete it.', go: 'map', hl: '#mapSummary' },
      ] },
    { id: 'marks', aud: 'user', cat: 'Survey', title: 'Mark the photo: models, FOC route, text', kw: 'mark photo red box model proposed pole globe gt odc odf panel data rack handhole tower foc route draw line text comment note burn',
      steps: [
        { t: 'In a survey record, tap the **photo**: it opens full size. Then **✎ Box · FOC · Text** or **⊥ Model**.', hl: '#edPhoto', when: 'It is in a survey record (Capture, or a pin).' },
        { t: 'The tool icons at the top: **box** (round a spot), **model** (proposed pole, ODC, ODF panel, data rack, handhole, tower), **FOC route** and **text**; the colour dots set the colour of the next mark, or of the selected one. **Navy blue** means existing: its label reads EXISTING.', hl: '#boxModes', when: 'It is on the marking screen (tap the photo in a record).' },
        { t: 'A **proposed pole** is always a **Globe (GT)** pole: its type is set and locked when the Status is Proposed. Its model goes from the ground up to its top.' },
        { t: '**Data rack**: drag from the floor up to its top: an **empty rack**. Then **Proposed ODF (rack panel)** and drag over its place in the rack: it fits between the rails, in whole rack units. Moving the rack moves its ODF too.' },
        { t: '**FOC route**: draw the line with your finger (e.g. from pole to pole) and lift to finish. **Text**: tap where the comment goes and type it; tap it once to move it, again to change it.', hl: '#boxCanvas', when: 'It is on the marking screen.' },
        { t: 'Tap a mark to select it (move, resize, **Delete**), then **Done**. The marks are drawn on a copy of the photo; the original is kept, so you can change them later.', hl: '#boxDone', when: 'It is on the marking screen.' },
      ] },
    { id: 'route', aud: 'user', cat: 'Survey', title: 'Link the cable route', kw: 'route span link poles cable capture order undo clear angle long span cable type figure 8 72c light 12c ug 144c air-blown aerial underground ae method',
      steps: [
        { t: 'Tap the **route** button on the map.', go: 'map', hl: '#routeBtn', when: 'It shows in a Survey project.' },
        { t: 'Choose the **CABLE** first: *AE Figure 8 72C FOC*, *Light cable 12C* (both aerial, AE) or *UG 144C air-blown fiber* (underground, UG). Each span you link takes it; the map draws each cable in its own colour (UG dotted, grey = not set).', hl: '#rbCable', when: 'It shows after you tap the route button.' },
        { t: 'Tap a pole, then the next pole, to link them. Tap a linked pair again to unlink it. With another cable chosen, tapping a linked pair gives that span the new cable instead (tap it again to unlink). **Set on all spans** gives every span the chosen cable; **Undo** goes back.', hl: '#rbHint', when: 'It shows after you tap the route button.' },
        { t: '**Link in capture order** links the poles in the order they were taken (gaps longer than the admin\'s limit are skipped). **Undo** and **Clear** if needed.', hl: '#rbAuto', when: 'It shows after you tap the route button.' },
        { t: 'Tap **Done** when finished. Spans longer than the maximum span and angle poles are flagged. The bar sums each cable; Export → FORMAT **Route and spans · Excel** lists every span with its cable and method, the KMZ draws one line per cable run and the DXF puts each cable on its own layer.', hl: '#rbDone', when: 'It shows after you tap the route button.' },
      ] },
    { id: 'drawing', aud: 'user', cat: 'Survey', title: 'Drawing and Find', kw: 'drawing dxf preview plan utm find search pin id element status defect labels fit',
      steps: [
        { t: 'In an As-Plan or As-Built survey, **Drawing** on the bottom bar shows the project as the DXF draws it: poles, route and spans in UTM metres. In other tasks the same button is **Find**.', go: 'map', hl: '#drawBtn' },
        { t: 'Drag to pan, pinch or scroll to zoom, tap a point to see it. **Fit** shows everything, **Labels** turns the IDs on or off, **Export DXF** makes the file.', hl: '#drawFit', when: 'It is in the Drawing (As-Plan or As-Built survey).' },
        { t: 'For the plan on your company\'s AutoCAD template, use Export → **AutoCAD · DXF** → DRAWING *On the company plan template* (see *Plan DXF on the company template*).' },
        { t: '**Find**: type an ID, element, status or defect and tap a result: the map goes to that pin. **All records ›** opens the full list.', hl: '#findQ', when: 'It is in Find (tasks other than As-Plan and As-Built).' },
        { t: 'On the map, pole and span labels move apart (or hide) so they do not overlap; zoom in to see them all.' },
      ] },
    { id: 'surveyexport', aud: 'user', cat: 'Survey', title: 'Survey exports (KMZ, DXF, CSV, photos)', kw: 'export kmz google earth dxf autocad csv excel photos zip design lld format',
      steps: [
        { t: 'Tap **Export**.', go: 'map', hl: '#exportBtn' },
        { t: 'Choose the export under **FORMAT** at the top: one export is shown at a time.', go: 'export', hl: '#xFormat' },
        { t: '**Several formats at once, in one ZIP**: tick the formats you need (e.g. KMZ, DXF and the completion report) and make them all in one file.', go: 'export', hl: '#xMulti' },
        { t: '**Google Earth · KMZ**: pins named by pole ID with the photo in each balloon, and the route as one continuous line from end to end (long spans also in their own folder). **AutoCAD · DXF**: poles at UTM 51N with their IDs, details, photos and the route (keep the files of the ZIP together).', go: 'export', hl: '#doKmz', when: 'The survey exports show in a Survey project.' },
        { t: '**Table · CSV**, **Route and spans · Excel** and **Geotagged photos · ZIP** too. Each card has its **Options**; the defaults are in Settings → Exports and files.', go: 'export', hl: '#doCsv', when: 'The survey exports show in a Survey project.' },
        { t: '**Completion report · PDF** marks the task complete and sends the date to the online sheet.', go: 'export', hl: '#doCompletion' },
      ] },
    { id: 'plandxf', aud: 'user', cat: 'Survey', title: 'Plan DXF on the company template', kw: 'dxf autocad template seed plan geo sheet keymap vicinity title block legend grid 1100 roads street names openstreetmap drafting',
      steps: [
        { t: 'Export → FORMAT **AutoCAD · DXF**. Once your admin shares the plan template, DRAWING is already **On the company plan template**: nothing to choose. (*Simple* is the older drawing: points and photos at UTM.)', go: 'export', hl: '#dxfMode', when: 'It is on the DXF card: Export → FORMAT AutoCAD · DXF, in a Survey project.' },
        { t: 'The template comes from your admin **by itself**: once it is shared, the app (website and Android) gets it in the background and keeps it, and the card shows **✓ Plan template ready**. Not there yet? Tap **Get the template**, or just **Export DXF** (it is fetched first). A newer one from the admin replaces it by itself. If your admin\'s online sheet is older, the website may offer *Open in Drive* and *Load the downloaded file* instead. The app does not carry the template (company property).', go: 'export', hl: '#dxfTplBox', when: 'It shows under DRAWING when *On the company plan template* is chosen.' },
        { t: 'Tap **Export DXF**. You get a ZIP: **unzip it into one folder** (the DXF shows the pictures next to it): the DXF on the template, a photo of each pole, the street map of the vicinity and a README listing the fields left blank. Every sheet of the template is kept: title, table of contents, legend, vicinity map, keymap, **one GEO sheet per 440 m grid cell the route crosses (1:1100)**, and the PMI; sheet numbers, index keys, the date and *Exported by* are filled.', go: 'export', hl: '#doDxf', when: 'The survey exports show in a Survey project.' },
        { t: 'On the drawing, with the template\'s own models: each pole **beside its road**, on the side of its pin, with **its photo** beside it, upright (proposed pole: PROP.POLE / height / clamp; existing pole: material / pole tag; all its labels in one direction; smaller where poles stand close), the cable **red** (new) on the **road side** of the poles, a **broken line** when aerial and solid underground, through the end of a **new arm**; **guys** against the pull of the cable (a head guy in line with it); loops, closures, NAPs, the site and ODF; span lengths (over the maximum span in red); the latitude / longitude of each pole (its GPS position).' },
        { t: 'Roads from OpenStreetMap (online, or the offline map pack): their width by class (primary 12 m, secondary 9, tertiary 7.5, residential 6, service 4), rounded corners, one outline where roads meet, street names, bridges, and **named buildings and places** nearby. The **vicinity map** shows the street map of the area with the route in red. Labels are placed where they do not overlap as far as there is room: check crowded spots in AutoCAD. Fields the app does not know stay blank.' },
      ] },
    { id: 'boq', aud: 'user', cat: 'Survey', title: 'BOQ / BOM in the As-Plan and As-Built', kw: 'boq bom size sizes clamp owner electric pldt dito converge new globe pole 7.5m 9.14m 10.6m 7a 7ar light odf 12f 24f 48f 72f 144f 288f apc upc closure 12c 24c 48c 72c 144c 288c as-plan as-built planned built difference materials arm double arm extension alley guy guying head guy side guy sidewalk down guy mloop maintenance loop region quantities detailed engineering foc length',
      steps: [
        { t: 'The BOQ is part of the **As-Plan Creation** survey (what the plan needs) and the **As-Built Creation** survey (what was built). Audit, PAT, defect cleanup and FAT have no sizes. Open a record: tap **Capture** for a new one, or a pin for one you have.', go: 'map', hl: '#captureBtn' },
        { t: 'In the record, **Size · for the BOQ / BOM** (under Identification): tap the size, tap it again to clear (a list of more than 4, e.g. the ODF and closure sizes, is a dropdown: choose it there; your admin sets the lists). An **existing pole**: its **owner** (Electric, PLDT, DITO, CONVERGE, or **+ Other**) and **clamp size** (5-7, 8-9, 10-12). A **proposed / new Globe pole**: its **size** (7.5m, 9.14m, 10.6m), **class** (7A, 7AR, Light) and clamp size.', hl: '#boqBox', when: 'It is in the record of a pole, an ODF or a closure, in an As-Plan or As-Built project.' },
        { t: 'A pole also has **NEW ARM** (single, double, extension 26" or 44.5", 10-pin alley arm), **NEW GUYING** (tap each one it needs: head, side, sidewalk, sidewalk head, pole-to-pole, down guy) and **MAINTENANCE LOOP** (tap **MLoop 15 m** when the cable is looped at that pole; your admin sets the length).', hl: '#boqBox', when: 'It is in the record of a pole, in an As-Plan or As-Built project.' },
        { t: '**ODF**: 12F to 288F and **APC** or **UPC**. **Closure**: 12C to 288C. Whether it is new or existing is the record\'s **Status**.' },
        { t: 'Projects → Project details → **REGION (BOQ)**: the GPS suggests the region (e.g. Region 12); choose it to confirm. It is approximate near a regional border, so check it.', go: 'projectDetails', hl: '#curRegion', when: 'In an As-Plan or As-Built project: Projects → Project details.' },
        { t: '**As-Built**: load the **As-Plan KMZ** (exported from G-eSAA) as the project\'s reference here. Each As-Built element then starts with its planned sizes and status (the same ID, else the nearest planned one within 15 m). The purple line in the record shows the plan; it turns orange when what was built differs, with **Use the planned sizes**.', go: 'projectDetails', hl: '#refLoad', when: 'In an As-Built project: Projects → Project details → KMZ reference.' },
        { t: 'The BOQ comes out with the survey: a **BOQ / BOM page** in the **Completion report**, a **BOQ sheet** in **Route and spans · Excel**, and on its own as **BOQ / BOM sizes · Excel**. In the As-Built it shows **Planned, Built and the Difference**, the planned elements not found and what was built outside the plan.', go: 'export', hl: '#doBoq' },
        { t: 'Both Excel files also have a **Survey quantities** sheet: span length by cable and method (AE / UG), maintenance loops, FOC length with the loops, **detailed engineering** (the FOC length without the loops), new poles by size, arms, guying, clamps, ODF, closures, NAPs and the region, each with a code for the BOQ rules.' },
      ] },
    { id: 'pat', aud: 'user', cat: 'PAT, defect cleanup and FAT', title: 'Record a PAT (defects as found)', kw: 'pat provisional acceptance defect deficiency punchlist major minor note md d n where photo add',
      steps: [
        { t: 'Make a project with task category **PAT** and fill its form details here (location / site, vendor, representatives, inspection type and date).', go: 'projectDetails', hl: '#curMore' },
        { t: 'Record only the elements **with defects**: stand at the defect and tap **Capture**. (This is the real app: the record is saved in the open project.)', go: 'map', hl: '#captureBtn' },
        { t: 'Photograph **the defect itself** with the **shutter**: that photo becomes the as-found photo of the defect.', hl: '#shutter', when: 'The shutter is in the camera: tap Capture first.' },
        { t: 'In the defect form choose **Where**, the **Defect** (one or more), the category **Major (MD)**, **Minor (D)** or **Note (N)**, add notes, then tap **Add to punchlist**. A new PAT record cannot be saved without a defect.', hl: '#defAdd', when: 'The defect form opens after the photo.' },
        { t: 'More defects on the same element: **+ Add** under Deficiencies. The pin turns **red** (open).', hl: '#addDefBtn', when: 'It is in the record, under Deficiencies.' },
        { t: 'Tap **Save** to keep the record.', hl: '#edSave, #edSaveTop', when: 'It is in the record.' },
        { t: 'Who records: the admin company\'s inspectors, and the vendors too when the admin allows it.' },
      ] },
    { id: 'nodefects', aud: 'user', cat: 'PAT, defect cleanup and FAT', title: 'No defects found', kw: 'no defects none clean pass fat done site photo complete pat',
      steps: [
        { t: 'On a PAT with no defect recorded, Projects shows **✓ No defects found · complete the PAT (FAT done)**. Tap it.', go: 'projects', hl: '#noDefBtn', when: 'It shows on a PAT that is not completed and has no defect yet.' },
        { t: 'Take the **site photo** with the shutter: it is the evidence of the inspection (its GPS position, time and your name are kept).', hl: '#shutter', when: 'The camera opens after you tap No defects found.' },
        { t: 'Choose the element if you like, then tap **Save**.', hl: '#edSave, #edSaveTop', when: 'The record opens after the photo.' },
        { t: 'The PAT is completed and the FAT is recorded as done the same day: no defect cleanup or FAT is needed. The reports say *No deficiencies found*.' },
      ] },
    { id: 'patdone', aud: 'user', cat: 'PAT, defect cleanup and FAT', title: 'Complete and share the PAT', kw: 'complete lock pat share kmz send contractor cleanup start',
      steps: [
        { t: 'When every defect is recorded: Projects → **✓ Mark task complete** → **Complete and lock**. The PAT is locked; only the admin can reopen it.', go: 'projects', hl: '#doneBtn' },
        { t: 'Export → FORMAT **Deficiency List · PDF** for signing (see Reports and files).', go: 'export', hl: '#doPdf' },
        { t: '**Share PAT KMZ · for defect cleanup / FAT** sends it to the contractor (Viber, email, Drive…). Its G-eSAA data is locked: Google Earth shows the map, only G-eSAA phones of your list read the records.', go: 'projects', hl: '#sendPat', when: 'It shows on a PAT, defect cleanup or FAT project.' },
        { t: 'Or, on this phone: **🛠 Start the defect cleanup**.', go: 'projects', hl: '#startCleanup', when: 'It shows once the PAT is completed.' },
      ] },
    { id: 'cleanup', aud: 'user', cat: 'PAT, defect cleanup and FAT', title: 'Defect cleanup (contractor)', kw: 'cleanup rectify rectification fix photo of the fix fixed no photo comment next pin contractor shared file',
      steps: [
        { t: 'Projects → **📂 Open a shared file** → the PAT KMZ → **Start the defect cleanup**. The map opens on the PAT\'s pins with the first item to fix; the project takes the PAT\'s site, vendor and Globe representative.', go: 'projects', hl: '#openShared' },
        { t: 'Walk to each **red pin**: the strip above the bottom bar points to the nearest one. Tap a pin to open its card.', hl: '#visitCard', when: 'The card opens on the map when you tap a pin of a defect cleanup or FAT.' },
        { t: 'On each item: **📷 Photo of the fix** (or **Fixed, no photo**), and **💬 Comment** if needed. Every button saves at once.', hl: '#vcItems .acts .btn.primary', when: 'It is on the card of a pin with an open item.' },
        { t: 'Photograph the fixed item with the **shutter**.', hl: '#shutter', when: 'The camera opens after Photo of the fix.' },
        { t: '**Next pin ›** goes to the next nearest pin that still needs you.', hl: '#vcNext', when: 'It is on the card of a pin.' },
        { t: 'When every item is fixed: Projects → **✓ Mark task complete**, then **Share cleanup KMZ · for the FAT**.', go: 'projects', hl: '#doneBtn' },
      ] },
    { id: 'fat', aud: 'user', cat: 'PAT, defect cleanup and FAT', title: 'FAT: verify the fixes', kw: 'fat final acceptance verify accept reject reason inspector check fix',
      steps: [
        { t: 'The FAT starts only from a **completed defect cleanup**: on this phone with **✓ Start the FAT from the completed cleanup**, or from the shared cleanup KMZ (Open a shared file → **Start the FAT**).', go: 'projects', hl: '#startFat', when: 'It shows once the defect cleanup is completed.' },
        { t: 'Walk to each pin and tap it to open its card.', hl: '#visitCard', when: 'The card opens on the map when you tap a pin of the FAT.' },
        { t: '**✓ Accept**, **📷 Accept with photo**, or **✗ Reject** with the reason (the item goes back to open; the reason is kept and printed).', hl: '#vcItems .acts .btn', when: 'It is on the card of a pin with a fixed item.' },
        { t: 'Then export the final **Deficiency List** (as found → rectified → verified photos in Annex A) and the **Rectification progress** report, and **✓ Mark task complete**.', go: 'export', hl: '#doPdf' },
      ] },
    { id: 'records', aud: 'user', cat: 'PAT, defect cleanup and FAT', title: 'Records, pins and statuses', kw: 'records list filter open rectified verified status colors red blue teal green timeline',
      steps: [
        { t: 'Tap the strip above the bottom bar (or **Find** → **All records**) to open the records.', go: 'map', hl: '#mapSummary' },
        { t: 'Filter **All / Open / Rectified / Verified / No deficiency**, sort, and group by element; tap a group to open or close it.', go: 'records' },
        { t: 'Pin colours: **red** open deficiency, **blue** rectified and waiting for verification, **teal** all verified, **green** no deficiency.' },
        { t: 'Each item keeps its timeline: FOUND → RECTIFIED → VERIFIED, with who and when. A rejection keeps its reason.' },
      ] },

    { id: 'deflist', aud: 'user', cat: 'Reports and files', title: 'Deficiency List (PDF and Excel)', kw: 'deficiency list pdf excel form annex photos signature print office',
      steps: [
        { t: 'Export → FORMAT **Deficiency List · PDF**: the office form (PAT or FAT ticked, 15 items per page, signature blocks), then Annex A with the photo evidence of each item and Annex B with the inspection photo log.', go: 'export', hl: '#doPdf', when: 'It shows in a PAT, defect cleanup or FAT project.' },
        { t: '**Deficiency List · Excel**: the same form, editable, plus the punchlist table, the elements, the photo index and the people.', go: 'export', hl: '#doXlsx', when: 'It shows in a PAT, defect cleanup or FAT project.' },
        { t: '**Options** on each card: annexes, photo size, signature dates. The logos and header lines are set by your admin.' },
      ] },
    { id: 'kmzstamp', aud: 'user', cat: 'Reports and files', title: 'The KMZ inside every PDF', kw: 'kmz attached stamp pdf attachment paperclip sha-256 acrobat foxit firefox verify google earth',
      steps: [
        { t: 'Every PDF report (completion report, Deficiency List, rectification report) carries the KMZ of the same records, so the PDF can be compared with the map.' },
        { t: 'A small **KMZ ATTACHED** stamp at the **lower right of the first page** gives the file name and size, what it holds and its **SHA-256**.' },
        { t: 'To get the KMZ, open the PDF in **Adobe Acrobat Reader**, **Foxit** or **Firefox** and click the stamp, or open the attachments (paperclip) panel. Chrome, Edge and phone gallery viewers do not show attachments.' },
        { t: 'To check it is the same file, its SHA-256 must equal the one on the stamp (Windows: certutil -hashfile file.kmz SHA256; Mac: shasum -a 256 file.kmz).' },
      ] },
    { id: 'completion', aud: 'user', cat: 'Reports and files', title: 'Completion report and finishing a task', kw: 'completion report complete finish undo sheet date sign-off',
      steps: [
        { t: 'Export → FORMAT **Completion report · PDF**: page 1 says the task is complete (site, vendor, dates, what was recorded, sign-off); the photo pages follow.', go: 'export', hl: '#doCompletion' },
        { t: 'Making it marks the task complete, like Projects → **✓ Mark task complete**; the online sheet gets the date.', go: 'projects', hl: '#doneBtn' },
        { t: '**Undo complete** clears it again (and the on-site approval with it). A completed PAT is reopened only by the admin.' },
      ] },
    { id: 'approval', aud: 'user', cat: 'Reports and files', title: 'Approval on site (inspector\'s QR code)', kw: 'approve approval on site qr inspector approver signature id number accept sign-off pat fat as-plan as-built audit',
      steps: [
        { t: 'When the task is completed, the inspector approves it on site: Projects → **Scan the inspector\'s approval QR**.', go: 'projects', hl: '#apprScan', when: 'It shows on a completed task.' },
        { t: 'The inspector shows it on their phone: Settings → **On-site approval QR**. It is signed with the admin key of the company list, holds their name, company ID no., mobile and email, and is valid 10 minutes (it renews every minute while open).', go: 'settings', hl: '#apprShowBtn', when: 'It shows on the phone of an admin user of the admin company.' },
        { t: 'Only the right approver is accepted: a **PAT/FAT inspector** approves the PAT, the defect cleanup and the FAT; the **As-Plan**, **Audit** and **As-Built approvers** approve those surveys (the admin sets the jobs). A copied, changed or old code is refused.' },
        { t: 'The task keeps who approved, the time and the GPS position. The **Completion report** prints it in a green box and next to the signature line, so the PDF stands without a written signature; signing the printed copy is still possible.', go: 'export', hl: '#doCompletion' },
      ] },
    { id: 'share', aud: 'user', cat: 'Reports and files', title: 'Share, open and back up files', kw: 'share project send colleague open shared file backup restore zip several projects edited unauthorized tampered',
      steps: [
        { t: '**Share** on a project card sends that project (records and photos) as one file to a colleague of your company. On a PAT or a cleanup it asks: the **project file**, or the locked **KMZ** for the next stage.', go: 'projects', hl: '#curTools .tmtool.share' },
        { t: 'Share opens the phone\'s **share sheet**: WhatsApp, Viber, email, Drive, **Save to Files**, and to a phone nearby **Quick Share** (Android) or **AirDrop** (iPhone). On the website a panel comes first: tap **Share…** there. Chrome on Android cannot hand a .zip or .kmz from a website to other apps: then **Save to phone** and send it from the Files app, or use the Android app, which shares any file.' },
        { t: '**To a Globe representative beside you, without signal**: Android to Android, Share → **Quick Share** (Bluetooth / Wi-Fi Direct, no data used); iPhone to iPhone, **AirDrop**. Android to iPhone has no common offline way: send it by a chat app when there is signal, or show the completion report (PDF) on your screen. The other phone opens a project or PAT / cleanup KMZ with Projects → **📂 Open a shared file** (its G-eSAA must be on your company list for a locked KMZ).' },
        { t: 'Projects → **📂 Open a shared file** opens a shared project, a PAT or cleanup KMZ, a backup ZIP, or several projects from a colleague.', go: 'projects', hl: '#openShared' },
        { t: 'Projects → **📤 Share several projects** puts several projects in one file.', go: 'projects', hl: '#bulkShareBtn', when: 'It shows when there are projects on this phone.' },
        { t: 'Export → FORMAT **Backup** → **Back up project** or **Restore backup**: everything in this project in one file.', go: 'export', hl: '#doBackup' },
        { t: '**⚠ KMZ edited by unauthorized personnel** means a locked KMZ was changed after it was shared (or damaged on the way): it is refused. Ask for the original file.' },
      ] },
    { id: 'delete', aud: 'user', cat: 'Reports and files', title: 'Delete a project', kw: 'delete remove project request code approval admin 6-digit',
      steps: [
        { t: 'Tap **Delete** on the project\'s card (in Projects, the open project and every other one).', go: 'projects', hl: '#curTools .tmtool.del' },
        { t: 'Confirm with **Delete project**, or **Keep**. Make a backup or share it first if you still need it.', when: 'The question shows after Delete.' },
        { t: 'A **completed** project needs an admin\'s approval first: the app shows a **request code** (e.g. 674-8SC). Send it to your admin, then type the admin\'s **6-digit approval code** (it works only for that request), or an admin who is with you types the admin PIN. The sample project needs no approval.' },
      ] },
    { id: 'fieldsettings', aud: 'user', cat: 'Settings', title: 'Camera and other settings', kw: 'settings camera id scan orientation button position left right sharpness exports stamps text size help',
      steps: [
        { t: 'Settings → **Camera**: scan the ID after each photo, the live ID reader, how IDs are painted, the camera button position (right, center or left hand) and the photo sharpness.', go: 'settings', hl: '#goCamera' },
        { t: 'Settings → **Exports and files**: photo sizes and stamps, KMZ, PDF and DXF defaults, where files are saved.', go: 'settings', hl: '#goExports' },
        { t: 'In the camera, **0.5×** shows when the phone lets the app use its ultra-wide lens; many phones give a web app 1× and up only.' },
        { t: 'At the bottom of Settings: **Text size**, and keep the help text open on every screen.', go: 'settings' },
      ] },
    { id: 'offline', aud: 'user', cat: 'Settings', title: 'Offline maps', kw: 'offline map pack no signal download import pmtiles satellite street layer tiles area download protomaps openstreetmap',
      steps: [
        { t: 'Before going to a no-signal area, on Wi-Fi: Settings → **Maps** → Offline map packs: download your area\'s pack (from your admin\'s list) or **Import a pack file**.', go: 'settings', hl: '#goMaps' },
        { t: 'Or **Download an area for offline use**: the map view or the project\'s area (about 1 km round its records), cut from the Protomaps basemap build (OpenStreetMap data) and kept as a pack, zoom 0 to 15. A town is a few MB; a very big area is refused (zoom in). Cancel stops it.', go: 'maps', hl: '#areaDl' },
        { t: 'With no signal the map switches to it by itself. The **layer** button also cycles street → satellite → offline.', go: 'map', hl: '#layerBtn' },
        { t: 'Map tiles you viewed online are kept too; Settings → **Storage** shows how much space they use.', go: 'settings', hl: '#goStorage' },
      ] },
    { id: 'account', aud: 'user', cat: 'Settings', title: 'Invite a coworker, move phones, reset', kw: 'invite coworker qr link move phone new phone reset user change company',
      steps: [
        { t: 'Settings → **Invite a coworker (QR)**: a small QR code and **Send the invite link** for someone of your company. The coworker scans it or taps the link (in the G-eSAA app: *Open in the G-eSAA app*), then fills in name, mobile and email; the company comes from the invite. A company key inside stays hidden; send it only inside your company.', go: 'settings', hl: '#inviteBtn', when: 'It shows once you joined a company list.' },
        { t: '**Move to another phone…**: one QR code or link with your company list and your details. Move projects and photos with **Share** on each project card (or Export → Back up project).', go: 'settings', hl: '#moveBtn' },
        { t: '**Reset user…** removes your name, company and key from this phone; projects and photos stay.', go: 'settings', hl: '#resetUser' },
      ] },
    { id: 'sync', aud: 'user', cat: 'Settings', title: 'The online sheet (sites and progress)', kw: 'online sheet google sync sites progress dates offline hourly manual',
      steps: [
        { t: 'Your sites come from the online Google Sheet, and the completion dates go back to it.' },
        { t: 'Settings → **Sync with the online sheet**: on every change (recommended), every hour, or only when you tap Sync. **Sync online sheet** reads it now.', go: 'settings', hl: '#syncModeBox', when: 'It shows when your company list has an online sheet.' },
        { t: 'Offline, the dates wait on the phone and are sent when you are back online.' },
      ] },
    { id: 'help', aud: 'user', cat: 'Settings', title: 'Problems and the app log', kw: 'problem error support log send refused photo slow',
      steps: [
        { t: 'Settings → **App log**: the errors and timings. **Send log** to your admin or support when something goes wrong.', go: 'settings', hl: '#goLog' },
        { t: 'A refused photo: check the GPS (green shutter), the light and the focus. Photos are taken live; in PAT, cleanup and FAT they must be taken within 1 km of the element.' },
      ] },

    /* ===================== ADMIN GUIDE (admin company only) ===================== */
    { id: 'adm-open', aud: 'admin', cat: 'Administration', title: 'Open Administration', kw: 'admin pin administration manage company list policies',
      steps: [
        { t: 'Settings → the **company list** row (under COMPANY LIST, with your list\'s name), or **Manage (admin)**.', go: 'settings', hl: '#goAdmin' },
        { t: 'Type the **admin PIN**, then tap **Continue**.', go: 'admin', hl: '#admUnlock', when: 'The PIN is asked when Administration opens. Already unlocked: tap Next.' },
        { t: 'Each section folds: tap its heading to open or close it.' },
        { t: 'Everything here goes to every phone of the list when you tap **Save and share the list** (at the bottom). Tap it only when you changed something.', go: 'admin', hl: '#admSave', when: 'Type the admin PIN and tap Continue first: then the ring shows it.' },
        { t: 'Staff of the admin company with the PIN are admins and inspectors. Use **Change the admin PIN** when someone leaves.', go: 'admin', hl: '#admChangePin', when: 'Type the admin PIN and tap Continue first: then the ring shows it.' },
      ] },
    { id: 'adm-sheet', aud: 'admin', cat: 'Administration', title: 'Connect the online Google Sheet', kw: 'google sheet apps script deploy web app url read key admin key test connection project data region territory update script',
      steps: [
        { t: 'In the sheet: Extensions → Apps Script, paste **PoleCam-online-sheet.gs**, Save, Run **setup**, then Deploy → New deployment → Web app (Execute as: Me; Who has access: Anyone). Copy the URL ending in /exec.' },
        { t: 'Administration → **Online Google Sheet**: paste the **Web app URL**…', go: 'admin', hl: '#admUrl', when: 'Type the admin PIN and tap Continue first: then the ring shows it.' },
        { t: '…the **Read key** (the sheet\'s Settings tab) and the **Admin key**, then tap **Test connection**.', go: 'admin', hl: '#admTest', when: 'Type the admin PIN and tap Continue first: then the ring shows it.' },
        { t: 'Updating the script: paste the new code, Save, Run **setup** once, then Deploy → Manage deployments → Edit → Version: **New version**. Never New deployment: that changes the URL and phones stop reading the sheet.' },
        { t: 'The sites come from the **Project Data** tab (Tasks source tab). Its **Region** and **Territory** columns narrow what each user sees (script v2.25; v2.27: a user with nothing ticked gets no site).' },
      ] },
    { id: 'adm-companies', aud: 'admin', cat: 'Administration', title: 'Companies, admin company and admin users', kw: 'companies vendors refresh admin company admin users email inspector',
      steps: [
        { t: 'Companies and vendors come only from the sheet\'s **Company List** / **Companies** tab: edit them there, then tap **Refresh from the sheet**.', go: 'admin', hl: '#admCoRefresh', when: 'Type the admin PIN and tap Continue first: then the ring shows it.' },
        { t: '**Admin company**: its staff with the PIN are admins and inspectors; everyone else is a contractor user.', go: 'admin', hl: '#admOwner', when: 'Type the admin PIN and tap Continue first: then the ring shows it.' },
        { t: '**Admin users**: best kept in the online sheet\'s **Admin users** tab (email, name, company ID no., mobile, job; script v2.28). Refresh from the sheet shows them here; Save puts them in the list.', go: 'admin', hl: '#admUsersSheet, #admUsers', when: 'Type the admin PIN and tap Continue first: then the ring shows it.' },
        { t: 'The **job** decides who approves what on site: *PAT/FAT inspector* (PAT, defect cleanup and FAT), *As-Plan approver*, *Audit approver*, *As-Built approver* (several in one cell is fine). Without the sheet tab, type one line per user: the email, then the job. Blank = anyone of the admin company with the PIN; once any user has a job, a user with none approves nothing.' },
      ] },
    { id: 'adm-invite', aud: 'admin', cat: 'Administration', title: 'Invite a company\'s users (company keys)', kw: 'invite company key makecompanykeys first user qr link contractor join',
      steps: [
        { t: 'In the Apps Script editor run **makeCompanyKeys** once: each company gets a key in the CompanyKeys tab.' },
        { t: 'Administration → **Invite a company\'s users**: paste one company\'s key (the field hides it)…', go: 'admin', hl: '#admInvKey', when: 'Type the admin PIN and tap Continue first: then the ring shows it.' },
        { t: '…and tap **Make the invite**. The sheet confirms whose key it is; a wrong key is refused.', go: 'admin', hl: '#admInvMake', when: 'Type the admin PIN and tap Continue first: then the ring shows it.' },
        { t: 'Show the **QR code** or **Send the invite link** to that company\'s first user; they then invite their coworkers.' },
        { t: 'Users never see or type a key. Anyone who has an invite can join that company: to stop old invites, change the company\'s key in the sheet and make new ones.' },
      ] },
    { id: 'adm-logos', aud: 'admin', cat: 'Administration', title: 'Logos and form wording', kw: 'logo image header department line form wording signatory legend inspection types',
      steps: [
        { t: '**Deficiency List form and report logos** → **Choose image…** for the left and the right logo; **Built-in** puts the bundled one back. They print on the form and on the completion and rectification reports.', go: 'admin', hl: '#admLogoL', when: 'Type the admin PIN and tap Continue first: then the ring shows it.' },
        { t: 'The header wording below: company name, address, **Department line 1 and 2**, signatory titles, inspection types, legend and the rectified-date sub-label.', go: 'admin', hl: '#pfmDept1', when: 'Type the admin PIN and tap Continue first: then the ring shows it.' },
      ] },
    { id: 'adm-checklist', aud: 'admin', cat: 'Administration', title: 'Deficiency checklist', kw: 'checklist defects category add defect list items',
      steps: [
        { t: 'Choose a **Category**…', go: 'admin', hl: '#setDefCat', when: 'Type the admin PIN and tap Continue first: then the ring shows it.' },
        { t: '…and edit its **Defects**, one per line.', go: 'admin', hl: '#setDefItems', when: 'Type the admin PIN and tap Continue first: then the ring shows it.' },
        { t: '**Add category** for a new one (e.g. Manhole). A category with no defects left is removed when you save. The changes reach every phone with the next list version.', go: 'admin', hl: '#admAddCat', when: 'Type the admin PIN and tap Continue first: then the ring shows it.' },
      ] },
    { id: 'adm-standards', aud: 'admin', cat: 'Administration', title: 'Field standards and who records', kw: 'field standards maximum span angle pole prefixes vendors record sharpness pole owners boq',
      steps: [
        { t: '**Maximum span**, **Angle pole from (°)**, the gap limit of *Link in capture order*, the **maintenance loop (MLoop) length** (15 m unless you change it) and **Extra pole prefixes for everyone**.', go: 'admin', hl: '#setMaxSpan', when: 'Type the admin PIN and tap Continue first: then the ring shows it.' },
        { t: '**Sizes for the BOQ / BOM and pole details**: the pole owners, clamp sizes, new Globe pole sizes and classes, ODF sizes and connectors, closure sizes, new arms, guying and the pole details, one value per line. Add, rename or remove; empty = the built-in list. A list of more than 4 shows as a dropdown in the record.', go: 'admin', hl: '#admBoqBox', when: 'Type the admin PIN and tap Continue first: then the ring shows it.' },
        { t: '**Vendors record PAT defects and accept fixes at FAT**: on = vendors may record; off = only the admin company does.', go: 'admin', hl: '#admVendorRec', when: 'Type the admin PIN and tap Continue first: then the ring shows it.' },
        { t: '**Photo sharpness required**: Strict (recommended) or Normal.', go: 'admin', hl: '#admQuality', when: 'Type the admin PIN and tap Continue first: then the ring shows it.' },
      ] },
    { id: 'adm-kmz', aud: 'admin', cat: 'Administration', title: 'Shared KMZ lock', kw: 'kmz password lock shared protect tamper edited unauthorized google earth',
      steps: [
        { t: 'The G-eSAA data in the shared PAT, cleanup and FAT KMZ files is locked with the **KMZ password**; Google Earth still shows the map.', go: 'admin', hl: '#admKmzPass', when: 'Type the admin PIN and tap Continue first: then the ring shows it.' },
        { t: 'Best set in the online sheet: **Settings → KMZ password** (script v2.28). Administration then only shows it; every phone of the list gets it. Without it, a random password is suggested here: nobody types it. Do not put a company key in it.' },
        { t: 'A file changed outside G-eSAA is refused with **⚠ KMZ edited by unauthorized personnel**.' },
      ] },
    { id: 'adm-approve', aud: 'admin', cat: 'Administration', title: 'Approve a delete', kw: 'approve delete request code 6-digit approval completed project',
      steps: [
        { t: 'A user who deletes a completed project gets a **request code**.' },
        { t: 'Administration → **Approve a delete**: type the code…', go: 'admin', hl: '#admReq', when: 'Type the admin PIN and tap Continue first: then the ring shows it.' },
        { t: '…tap **Get code**, and give them the **6-digit approval code**. It works only for that request.', go: 'admin', hl: '#admReqGo', when: 'Type the admin PIN and tap Continue first: then the ring shows it.' },
        { t: 'When you are with the user, type the admin PIN on their phone instead.' },
      ] },
    { id: 'adm-packs', aud: 'admin', cat: 'Administration', title: 'Offline map packs for everyone', kw: 'map packs pmtiles google drive offline link size',
      steps: [
        { t: 'Upload each .pmtiles map pack to Google Drive and share it as "Anyone with the link".' },
        { t: 'Administration → **Offline map packs**: one line per pack, *name | Drive link | size in MB*. Users see them under Maps once they take this list version.', go: 'admin', hl: '#admPacks', when: 'Type the admin PIN and tap Continue first: then the ring shows it.' },
        { t: '**Area download source** (optional): users\' *Download an area* reads the Protomaps daily build, which Protomaps asks not to rely on for production. For heavy use, put a copy of a build on your own storage that allows range requests (e.g. Cloudflare R2) and enter its https address here.', go: 'admin', hl: '#admAreaSrc', when: 'Type the admin PIN and tap Continue first: then the ring shows it.' },
      ] },
    { id: 'adm-dxf', aud: 'admin', cat: 'Administration', title: 'Plan DXF template for everyone', kw: 'dxf template seed autocad google drive link plan export',
      steps: [
        { t: 'Prepare the seed from the company\'s AutoCAD plan template (`tools/dxf-seed/make_seed.py`, with the template exported as a text DXF) and upload it to Google Drive.' },
        { t: 'Administration → **Drawing template (DXF seed)**: paste its Drive link. Phones take it with the list and download it for Export → AutoCAD · DXF.', go: 'admin', hl: '#admDxfSeed', when: 'Type the admin PIN and tap Continue first: then the ring shows it.' },
        { t: 'The template is company property. *Anyone with the link* lets the Android app download it by itself, and anyone given the link can open it. With a link restricted to company accounts, users open it signed in, download the file and tap **Load template file…**.' },
      ] },
    { id: 'adm-save', aud: 'admin', cat: 'Administration', title: 'Save and share the list', kw: 'save share list version join link qr org.json tie website apk',
      steps: [
        { t: 'Tap **Save and share the list**: a new list version, signed with the admin PIN.', go: 'admin', hl: '#admSave', when: 'Type the admin PIN and tap Continue first: then the ring shows it.' },
        { t: 'With the online sheet (Admin key set), phones that joined take the new version by themselves; no QR code is shown. To add users, tap **Make an invite** (or Settings → **Share list**) and choose their company: the invite names it, so they do not choose it. Without the sheet, the join QR code and link show after Save.' },
        { t: '**Tie the app to this list** → **Download org.json**, and put it next to index.html on the website (and in the APK build): new users can then only join this list.', go: 'admin', hl: '#admOrg', when: 'Type the admin PIN and tap Continue first: then the ring shows it.' },
      ] },
    { id: 'adm-inspect', aud: 'admin', cat: 'Administration', title: 'Inspecting as the admin company', kw: 'inspector verify accept reject reopen pat undo complete all sites',
      steps: [
        { t: 'Admin company users record PAT defects, verify the fixes at the FAT (**✓ Accept**, **📷 Accept with photo**, **✗ Reject**) and reopen a completed PAT (Projects → **Undo complete**).' },
        { t: 'Sites: the admin company sees every company\'s sites from the sheet, narrowed by your own regions and territories (Your details).', go: 'profile', hl: '#pfAreaBox' },
      ] },
  ];
  root.GESAA_TUTORIAL = { version: '2.29', topics: T };
})(typeof self !== 'undefined' ? self : this);
